package dev.aether;
import dev.aether.ecs.*;import dev.aether.math.Vec3;import dev.aether.physics.*;import dev.aether.scene.Transform;import dev.aether.script.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AetherEngineTest{@Test void physicsMovesGravityBody(){World w=new World();w.addSystem(new PhysicsSystem());Entity e=w.create("falling");w.add(e,Transform.identity());w.add(e,new RigidBody(1,Vec3.ZERO,true));w.update(1);assertEquals(-9.81,w.get(e,Transform.class).orElseThrow().position().y(),1e-9);}@Test void structuralChangesAreDeferred(){World w=new World();Entity e=w.create("source");w.addSystem((world,dt)->world.destroy(e));w.update(0);assertFalse(w.exists(e));}@Test void entityCreatedDuringUpdateCanReceiveComponents(){World w=new World();w.addSystem((world,dt)->{Entity e=world.create("spawned");world.add(e,Transform.identity());});w.update(0);assertEquals(1,w.entityCount());assertEquals(1,w.view(Transform.class).size());}@Test void scriptLifecycleAndEngineState(){var e=Aether.createEngine();Entity x=e.world().create("scripted");int[] calls={0};e.world().add(x,new ScriptComponent(new Script(){public void onCreate(World w,Entity q){calls[0]++;}public void onUpdate(World w,Entity q,double dt){calls[0]++;}}));assertThrows(IllegalStateException.class,()->e.tick(0));e.start();e.tick(.016);assertEquals(2,calls[0]);e.close();}@Test void invalidTimeIsRejected(){assertThrows(IllegalArgumentException.class,()->new World().update(-.1));}}
